<div class="mx-auto max-w-4xl space-y-6"><div><p class="text-sm text-slate-500">Configure company identity and localization defaults.</p><h2 class="mt-1 text-2xl font-bold">System Settings</h2></div><form method="POST" action="{{ url('/system-settings') }}" enctype="multipart/form-data" class="rounded-xl border border-slate-200 bg-white shadow-sm">@csrf @method('PUT')<div class="border-b border-slate-200 px-6"><div class="flex gap-6" role="tablist"><button type="button" data-tab="identity" class="border-b-2 border-indigo-600 px-1 py-4 text-sm font-semibold text-indigo-600">Company Identity</button><button type="button" data-tab="localization" class="border-b-2 border-transparent px-1 py-4 text-sm font-semibold text-slate-500 hover:text-slate-700">Localization</button></div></div><div class="p-6"><section data-tab-panel="identity" class="space-y-5"><div><label class="mb-1.5 block text-sm font-medium">Company name</label><input name="company_name" required value="{{ old('company_name', $settings?->company_name) }}" class="w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"><x-input-error :messages="$errors->get('company_name')" class="mt-1" /></div><div><label class="mb-1.5 block text-sm font-medium">Company logo</label><div class="flex items-center gap-4"><div id="logo-preview" class="grid size-16 place-items-center overflow-hidden rounded-xl border border-dashed border-slate-300 bg-slate-50 text-xs text-slate-400">@if ($settings?->logo)<img src="{{ asset('storage/'.$settings->logo) }}" alt="Company logo" class="size-full object-cover">@else Logo @endif</div><div><input id="logo" type="file" name="logo" accept="image/*" class="block w-full text-sm text-slate-500 file:mr-4 file:rounded-lg file:border-0 file:bg-indigo-50 file:px-3 file:py-2 file:text-sm file:font-semibold file:text-indigo-700 hover:file:bg-indigo-100"><p class="mt-1 text-xs text-slate-500">PNG, JPG, or SVG. A preview appears before saving.</p></div></div></div></section><section data-tab-panel="localization" class="hidden space-y-5"><div><label class="mb-1.5 block text-sm font-medium">Date format</label><select name="date_format" class="w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500">@foreach (['Y-m-d', 'd/m/Y', 'm/d/Y'] as $format)<option value="{{ $format }}" @selected(old('date_format', $settings?->date_format ?? 'Y-m-d') === $format)>{{ $format }}</option>@endforeach</select></div><div><label class="mb-1.5 block text-sm font-medium">Time zone</label><select name="time_zone" class="w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500">@foreach (['Asia/Kabul', 'Asia/Dubai', 'Asia/Karachi', 'Europe/London', 'UTC'] as $zone)<option value="{{ $zone }}" @selected(old('time_zone', $settings?->time_zone ?? 'Asia/Kabul') === $zone)>{{ $zone }}</option>@endforeach</select></div></section><div class="mt-7 flex justify-end"><button class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white shadow-sm transition hover:bg-indigo-700">Save Settings</button></div></div></form></div>
@push('scripts')<script>const tabs=document.querySelectorAll('[data-tab]'),panels=document.querySelectorAll('[data-tab-panel]');tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(item=>{item.classList.remove('border-indigo-600','text-indigo-600');item.classList.add('border-transparent','text-slate-500');});tab.classList.add('border-indigo-600','text-indigo-600');panels.forEach(panel=>panel.classList.toggle('hidden',panel.dataset.tabPanel!==tab.dataset.tab));}));document.getElementById('logo')?.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;const image=document.createElement('img');image.className='size-full object-cover';image.src=URL.createObjectURL(file);document.getElementById('logo-preview').replaceChildren(image);});</script>@endpush
